def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 1:
        return 'C'
    opp = [h[1] for h in history]
    me = [h[0] for h in history]
    last_opp = opp[-1]
    last_me = me[-1]
    opp_c = sum(1 for x in opp if x == 'C')
    opp_d = n - opp_c
    my_c = sum(1 for x in me if x == 'C')
    my_d = n - my_c

    recent_w = 10 if n >= 10 else n
    recent = opp[-recent_w:]
    recent_c = sum(1 for x in recent if x == 'C')
    recent_rate = recent_c / recent_w

    long_w = 30 if n >= 30 else n
    long = opp[-long_w:]
    long_c = sum(1 for x in long if x == 'C')
    long_rate = long_c / long_w

    streak_d = 0
    for x in reversed(opp):
        if x == 'D':
            streak_d += 1
        else:
            break
    streak_c = 0
    for x in reversed(opp):
        if x == 'C':
            streak_c += 1
        else:
            break

    if n < 6:
        if last_opp == 'D':
            return 'D'
        return 'C'

    if long_rate <= 0.12:
        if rng.random() < 0.05:
            return 'C'
        return 'D'

    if long_rate <= 0.3:
        if rng.random() < 0.2:
            return 'C'
        return 'D'

    if n >= 96:
        if long_rate >= 0.6:
            return 'D'
        if last_opp == 'D':
            return 'D'
        return 'C'

    if n >= 90:
        if long_rate >= 0.75:
            if rng.random() < 0.8:
                return 'D'
            return 'C'
        if last_opp == 'D':
            return 'D'
        return 'C'

    if n >= 80:
        if long_rate >= 0.85 and rng.random() < 0.4:
            return 'D'
        if last_opp == 'D':
            return 'D'
        return 'C'

    if last_opp == 'D':
        if streak_d >= 2:
            if recent_rate < 0.25:
                return 'D'
            if rng.random() < 0.1:
                return 'C'
            return 'D'
        if last_me == 'C':
            if rng.random() < 0.9:
                return 'D'
            return 'C'
        if rng.random() < 0.2:
            return 'C'
        return 'D'

    if streak_c >= 5 and long_rate >= 0.8 and n >= 15:
        if rng.random() < 0.08:
            return 'D'
        return 'C'

    if last_me == 'D':
        if long_rate >= 0.7:
            if rng.random() < 0.15:
                return 'D'
            return 'C'
        if recent_rate >= 0.5:
            return 'C'
        if rng.random() < 0.5:
            return 'C'
        return 'D'

    if recent_rate >= 0.8:
        if rng.random() < 0.05 and my_c > my_d:
            return 'D'
        return 'C'

    if recent_rate >= 0.5:
        if rng.random() < 0.9:
            return 'C'
        return 'D'

    if rng.random() < 0.35:
        return 'C'
    return 'D'
